// TH16 v1.00a Extra (st07) wave: GirlA02 two-sided formation.
// st07.ecl.txt MainSub01 1174-1187 -> pattern(); GirlA02 193-202 + GirlA02F 204-219 -> girl();
// GirlA02_at 221-242 -> girl_fire().

const TH16_BALL2: int = 432;   // 源 etSprite(0, 5, 6): type 5 / color 6
const TIME_LIMIT: int = 1324;
const OPENING_BUFFER: int = 120;

async sub girl_fire() {
    wait(10);                                             // 224
    for i in 0..1000 {                                    // 225-240: $A = 1000
        var a: angle = (rand(65536) - 32768) as angle;    // 236: etAngle(0, %RANDRAD, 0)
        // 228-237 配置: etAim(1) 固定方向、etCount(1,1)、etSpeed(1.2,2.2) 层数1 只取 1.2。
        // 234 EX ANIM a=1: 出生位置 -= 4 * velocity（1.2*4 = 4.8）。
        _ = fire(TH16_BALL2, 6,
                 $self_x - 4.8fx * cos(a),
                 $self_y - 4.8fx * sin(a),
                 1.2fx, a, none, none);
        wait(5);                                          // 238
    }
}

async sub girl(turn_to: angle) {
    // 205 dropSeason 属于季节奖励掉落，按口径省略。
    set_invuln(65535);
    set_hurtbox(12fx);                                    // 207: setHurtbox(24,24)
    set_hitbox(8fx);                                      // 208: setHitbox(16,16)
    move_vel(0, 90deg, 3fx, EASE_LINEAR);                 // 209: moveVel(pi/2, 3)
    move_vel(120, turn_to, 2fx, EASE_LINEAR);             // 210: moveVelTime(120, 0, 0, 2)
    spawn girl_fire();                                    // 211: @GirlA02_at() async
    loop { wait(1000); }                                  // 212-217: 120 帧后进入无限等待
}

async sub pattern() {
    wait(OPENING_BUFFER);
    for i in 0..40 {                                      // 1177/1185: $A = 40，每轮左右各一只
        var u: fx = ((rand(65536) - 32768) as fx) / 32768;      // 1180: %RANDF2
        _ = spawn_enemy(-64fx + u * 192fx, -16fx, 50, 0, 1000, 0, girl(0deg));
        wait(10);
        var u2: fx = ((rand(65536) - 32768) as fx) / 32768;     // 1182: %RANDF2
        // enmCreateM 子镜像=1：出生坐标按源保留，运动角水平镜像（0deg -> 180deg）。
        _ = spawn_enemy(64fx + u2 * 192fx, -16fx, 50, 0, 1000, 0, girl(180deg));
        wait(10);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
